// ClawdAssets.h — data types for the Clawdmeter assets ported to the SmallTV.
//
// Everything bulky lives in flash (PROGMEM). On the ESP8266 a 16-bit or 8-bit
// load straight from flash faults, so callers copy records out with memcpy_P /
// pgm_read_byte rather than dereferencing. The tables are generated by
// tools/clawd_assets.js (clawd_anims.h, clawd_fonts.h).
#pragma once
#include <stdint.h>
#include <string.h>

#if defined(ARDUINO)
#include <pgmspace.h>
#else   // host build (tools/clawd_preview): flash is ordinary memory
#define PROGMEM
#define pgm_read_byte(p) (*(const uint8_t*)(p))
#define pgm_read_word(p) (*(const uint16_t*)(p))
#define memcpy_P memcpy
#endif

// One official Clawd animation. Frames are bounding-box crops of the shared
// 55x37 art stage; (ox, oy) is the crop origin on that stage. Cells are palette
// indices packed two per byte (high nibble first), each frame byte-aligned.
struct ClawdAnim {
  char     name[16];
  uint8_t  w, h;              // frame size, cells
  uint8_t  ox, oy;            // crop origin on the 55x37 stage
  uint16_t frameCount;
  uint16_t loopStart, loopEnd;   // loopable region (whole file when nothing repeats)
  uint16_t frameBytes;        // bytes per packed frame
  uint16_t palette[16];       // RGB565, index 0 = background (true black)
  const uint8_t*  frames;     // PROGMEM, frameCount * frameBytes
  const uint16_t* holds;      // PROGMEM, ms per frame
};

// A glyph of an LVGL 4 bpp bitmap font (lv_font_conv output, uncompressed).
struct ClawdGlyph {
  uint16_t cp;                // unicode code point (sorted ascending)
  uint16_t off;               // byte offset into the font bitmap
  uint16_t adv;               // advance, 1/16 px
  uint8_t  w, h;              // bitmap box
  int8_t   ox, oy;            // box offset from the pen / baseline
};

struct ClawdKern {
  uint8_t left, right;        // glyph indices in the subset
  int8_t  adv;                // advance adjustment, 1/16 px
};

struct ClawdFont {
  const uint8_t*    bitmap;   // PROGMEM, 4 bpp packed, high nibble first
  const ClawdGlyph* glyphs;   // PROGMEM
  const ClawdKern*  kerns;    // PROGMEM, sorted by (left, right); may be null
  uint8_t  glyphCount;
  uint16_t kernCount;
  uint8_t  lineHeight;        // px
  uint8_t  baseLine;          // px from the bottom of the line
};

// Copy animation `i` (descriptor only, ~60 B) out of flash.
static inline void clawdAnimGet(const ClawdAnim* table, int i, ClawdAnim& out) {
  memcpy_P(&out, &table[i], sizeof(ClawdAnim));
}

// Palette index of cell (x, y) of `frame` (cells outside the crop are 0).
static inline uint8_t clawdAnimCell(const ClawdAnim& a, uint16_t frame, int x, int y) {
  if (x < 0 || y < 0 || x >= a.w || y >= a.h) return 0;
  uint32_t i = (uint32_t)y * a.w + x;
  uint8_t b = pgm_read_byte(a.frames + (uint32_t)frame * a.frameBytes + (i >> 1));
  return (i & 1) ? (b & 0x0F) : (b >> 4);
}

static inline uint16_t clawdAnimHold(const ClawdAnim& a, uint16_t frame) {
  return pgm_read_word(a.holds + frame);
}
